// nextcuda's front door: its page's API and documents (nextcuda serve): the routes' types and a typed client.
// Generated by rpcgen from the #[route] handlers: do not edit; regenerate.
/* eslint-disable */

/** A page button: what it does and to what */
export interface Action {
  do: ActionDo;
  /** the model (enable, disable, gpus, load, unload, pin, unpin, move, pull, pull_cancel) */
  model?: string | null;
  /** enable, gpus: the cards ([] or none: any) */
  gpus?: unknown | null;
  /** disable: even while it runs */
  force?: boolean | null;
  /** restart: serve, switch, studio, video, or a kind */
  service?: string | null;
  /** measure, move: the drive */
  drive?: string | null;
  /** auto_pull, maintenance: on or off */
  on?: boolean | null;
  /** other keys */
  [key: string]: unknown;
}

/** What a page button does */
export type ActionDo = "enable" | "disable" | "gpus" | "load" | "unload" | "pin" | "unpin" | "config" | "restart" | "maintenance" | "measure" | "move" | "move_cancel" | "pull" | "pull_cancel" | "auto_pull";

/** A model a card offers that is not here yet */
export interface Available {
  id: string;
  kind: string;
  title?: string | null;
  about?: string | null;
  /** the cards it is made for, as its model card says */
  gpus?: string | null;
  bytes: number;
  downloaded: boolean;
  /** where it would go */
  drive: string;
  folder: string;
  fits: boolean;
  free: number;
  pull?: PullView | null;
  runs_here: boolean;
  why_not?: string | null;
  /** the licence of its weights, whether it allows commercial use (false: the pages tag it non-commercial), the conditions it puts on it */
  license?: string | null;
  commercial?: boolean | null;
  license_note?: string | null;
}

/** A card: its readings, its processes, the memory vouched for */
export interface CardState {
  index: number;
  name: string;
  pci: string;
  /** when it was read (unix seconds) */
  ts: number;
  vram_used_mb: number;
  vram_total_mb: number;
  busy_pct: number;
  temp_pkg?: number | null;
  temp_vram?: number | null;
  temp_vram_max?: number | null;
  temp_pcie?: number | null;
  temp_mctrl?: number | null;
  power_w?: number | null;
  pkg_power_w?: number | null;
  power_cap_w?: number | null;
  pcie: Pcie;
  host_load1: number;
  host_cpus: number;
  /** the energy counter since the front door started, joules */
  energy_j: number;
  fan_pct?: number | null;
  fan_rpm?: number | null;
  freq_mhz?: number | null;
  procs: Proc[];
  vouched: Vouched[];
  vouched_mb: number;
  vouched_headroom_mb: number;
  /** the models vouched for pass the card */
  overbooked: boolean;
}

/** Whether other models may run on a model's card */
export interface CoexistenceView {
  /** "shared" or "exclusive" */
  mode: string;
  shared_with: string[];
  exclusive_reason: string;
  peak_extra_gib?: number | null;
}

/** A model card's concurrency profile as the page shows it */
export interface ConcurrencyView {
  max_copies_per_card: number;
  recommended_copies: number;
  /** copies -> total throughput relative to one copy (null: unmeasured) */
  scaling: unknown;
  /** {date, card, method, notes} or null */
  measured: unknown;
  /** "measured" or "unmeasured" */
  status: string;
}

/** The settings file and what each setting is */
export interface Config {
  path: string;
  text: string;
  settings: SettingRow[];
  /** the file's lines that are no setting listed */
  other: SettingRow[];
  prefixes: SettingPrefix[];
}

/** A drive the models are (or may be) on */
export interface DriveView {
  id: string;
  disk: string;
  model: string;
  link?: string | null;
  link_gb_s?: number | null;
  device: string;
  fstype: string;
  mount: string;
  folder: string;
  size: number;
  free: number;
  /** what is kept free */
  margin: number;
  models_bytes: number;
  models: string[];
  /** its read speed as measured (system.drive.measure); null: not measured */
  measured?: unknown | null;
  measuring: boolean;
  rate_gb_s?: number | null;
}

/** The drives, the models' files on them, a move under way */
export interface DrivesView {
  drives: DriveView[];
  models: Record<string, ModelFiles>;
  move?: unknown | null;
  /** the drive being measured */
  measuring?: string | null;
  folders: string[];
}

/** Whether the server answers (and has its model loaded) */
export interface Health {
  /** ok, or loading (HTTP 503 then) */
  status: string;
}

/** The machine: memory, load, CPUs */
export interface HostStat {
  mem_total_mb: number;
  mem_avail_mb: number;
  load1?: number | null;
  cpus: number;
}

/** A PCIe link: its generation and lanes */
export interface Link {
  gen?: number | null;
  width: number;
}

/** Maintenance mode's notice, as callers see it */
export interface Maintenance {
  on: boolean;
  message: string;
  /** unix seconds */
  since: number;
  /** about when it ends; null: unknown */
  until?: number | null;
  retry_after_s: number;
  /** the words a refused call gets */
  notice: string;
  /** the key that lets a call through (the page's own copy) */
  bypass?: string | null;
}

/** A model's files on the drives */
export interface ModelFiles {
  bytes: number;
  files: number;
  missing: number;
  /** drive -> bytes on it */
  drives: Record<string, number>;
  /** it streams weights from its drive while it runs */
  streams: boolean;
  moving: boolean;
  /** drive -> whether it may move there */
  move: Record<string, MoveCheck>;
}

/** A model's state */
export type ModelState = "disabled" | "unloaded" | "loading" | "loaded" | "busy" | "ready";

/** A registered model: kind, enabled, its cards, its state, the memory vouched for */
export interface ModelView {
  id: string;
  kind: string;
  title?: string | null;
  arch?: string | null;
  enabled: boolean;
  /** pinned (system.pin): loaded and kept - no idle unload, never stopped for another model's room */
  pinned: boolean;
  /** seconds a request's rsvp_s still holds it loaded (0: not held) */
  held_s: number;
  /** copies of it loaded now, and its profile's recommended and maximum per card */
  copies_now: number;
  recommended_copies: number;
  max_copies_per_card: number;
  /** its model card's concurrency profile (status "unmeasured": the defaults) and coexistence */
  concurrency: ConcurrencyView;
  coexistence: CoexistenceView;
  gpus: number[];
  state: ModelState;
  /** a chat model that spans every card */
  spans: boolean;
  capabilities: string[];
  /** the methods it serves (image.generate ...) */
  methods: string[];
  /** card index -> MiB */
  vouch_mb: Record<string, number>;
  measured: boolean;
  headroom_mb: Record<string, number>;
  headroom_given: boolean;
  /** the port its page is on */
  page: number;
  /** the licence of its weights, whether it allows commercial use (false: the pages tag it non-commercial), the conditions it puts on it */
  license?: string | null;
  commercial?: boolean | null;
  license_note?: string | null;
}

/** Whether a model's files may move to a drive: what they need there, or why not */
export interface MoveCheck {
  need?: number | null;
  why?: string | null;
}

/** A card's PCIe link now, the most the card does and the most its slot does */
export interface Pcie {
  cur: Link;
  card_max: Link;
  slot_max: Link;
}

/** The ports the page links */
export interface Ports {
  video: number;
  chat_ui: number;
}

/** A process on a card */
export interface Proc {
  pid: number;
  vram_mb: number;
  /** nextcuda, or another program (python: its script) */
  program: string;
  /** another program's command line (its start) */
  args?: string | null;
  /** nextcuda's: the kind and command it runs (llm, image serve ...) */
  kind?: string | null;
  command?: string | null;
  /** the model's file, or its registry id where it is a registered one (model_id, title) */
  model?: string | null;
  model_id?: string | null;
  title?: string | null;
  port?: string | null;
  gpus?: string[] | null;
}

/** A model download's state */
export type PullState = "queued" | "downloading" | "verifying" | "done" | "failed" | "cancelled";

/** A model's download */
export interface PullView {
  model: string;
  kind?: string | null;
  title?: string | null;
  drive: string;
  folder: string;
  state: PullState;
  error?: string | null;
  bytes_total: number;
  bytes_done: number;
  pct: number;
  /** bytes a second */
  speed: number;
  eta_s?: number | null;
  started: number;
  ended?: number | null;
  /** the run its output is in */
  run: number;
}

/** A run by its id */
export interface RunId {
  id: number;
}

/** Something the page ran (this program with arguments): its output's tail */
export interface RunView {
  id: number;
  label: string;
  started: number;
  /** its exit code; null: running */
  rc?: number | null;
  out: string;
}

/** A front end or helper beside the models */
export interface Service {
  id: string;
  title: string;
  what: string;
  port: number;
  up: boolean;
  detail?: string | null;
  /** its page, on its own port */
  link?: string | null;
  /** its page through this door */
  href?: string | null;
  api?: string | null;
}

/** A family of settings (a prefix) */
export interface SettingPrefix {
  prefix: string;
  what: string;
  readers: string[];
}

/** A setting this program reads */
export interface SettingRow {
  name: string;
  group?: string | null;
  default?: string | null;
  what: string;
  /** the programs that read it */
  readers: string[];
  /** its value in the file; null: not there */
  file?: string | null;
  /** its value in this service's environment (which wins over the file) */
  env?: string | null;
}

/** The API tab: the token and the document with it filled in */
export interface Spec {
  /** the bearer token (this page's own copy) */
  token: string;
  /** the OpenAPI document of what the enabled kinds offer */
  spec: unknown;
}

/** The box at a glance (the page polls it) */
export interface State {
  ts: number;
  host: HostStat;
  cards: CardState[];
  models: ModelView[];
  services: Service[];
  /** the last runs, newest first */
  runs: RunView[];
  idle_minutes: number;
  ports: Ports;
  maintenance?: Maintenance | null;
  drives: DrivesView;
  available: Available[];
  pulls: PullView[];
  /** a request for a model not downloaded fetches it (NS_AUTO_PULL) */
  auto_pull: boolean;
}

/** An enabled model's memory vouched for on a card (chat and video models: one of the group, `of` them) */
export interface Vouched {
  model: string;
  kind: string;
  mb: number;
  headroom_mb: number;
  headroom_given: boolean;
  /** the memory is what it took when it ran (else an estimate) */
  measured: boolean;
  state: string;
  of?: number | null;
}

/** A route's failure: the words its body's `error` said, and the body. */
export class RouteError extends Error {
  constructor(message: string, readonly body: unknown) {
    super(message);
  }
}

function runtime(base: string, fetcher: typeof fetch) {
  const words = (e: any): string => (typeof e === "string" ? e : (e?.message ?? JSON.stringify(e)));
  const read = async (res: Response, u: string, ownError: boolean): Promise<any> => {
    const text = await res.text();
    let v: any = null;
    try {
      v = text ? JSON.parse(text) : null;
    } catch {
      throw new RouteError(`${u}: the answer is not JSON (HTTP ${res.status})`, text);
    }
    const failed = v !== null && typeof v === "object" && !Array.isArray(v) && v.error != null && (!ownError || v.ok === false);
    if (failed) throw new RouteError(words(v.error), v);
    return v;
  };
  return {
    url(path: string, req: object, query: boolean): string {
      const fields = req as Record<string, unknown>;
      const used = new Set<string>();
      let p = path.replace(/\{([^}]+)\}/g, (_, k: string) => {
        used.add(k);
        return encodeURIComponent(String(fields[k] ?? ""));
      });
      if (query) {
        const q = new URLSearchParams();
        for (const [k, v] of Object.entries(fields)) {
          if (used.has(k) || v === undefined || v === null) continue;
          for (const x of Array.isArray(v) ? v : [v]) q.append(k, String(x));
        }
        const s = q.toString();
        if (s) p += `?${s}`;
      }
      return base + p.slice(1);
    },
    async json(method: string, u: string, body?: BodyInit, type?: string, ownError = false): Promise<any> {
      const res = await fetcher(u, { method, body, headers: type ? { "content-type": type } : undefined });
      return read(res, u, ownError);
    },
    async either(method: string, u: string, body: unknown, ownError = false): Promise<any> {
      const form = body instanceof FormData;
      const res = await fetcher(u, { method, body: form ? body : JSON.stringify(body), headers: form ? undefined : { "content-type": "application/json" } });
      return read(res, u, ownError);
    },
    async blob(method: string, u: string, body?: BodyInit, type?: string): Promise<any> {
      const res = await fetcher(u, { method, body, headers: type ? { "content-type": type } : undefined });
      if ((res.headers.get("content-type") ?? "").startsWith("application/json")) return read(res, u, false);
      return res.blob();
    },
  };
}

export function routes(base = "", fetcher: typeof fetch = (u, i) => fetch(u, i)) {
  const r = runtime(base, fetcher);
  return {
    /**
     * Whether the front door answers
     * @route GET /health
     * @tags page
     */
    health: (): Promise<Health> => r.json("GET", r.url("/health", {}, true), undefined, undefined, false),
    /**
     * The OpenAPI document of what the enabled kinds offer (no token needed; its examples say <token>)
     * @route GET /openapi.yml
     * @alias /openapi.yaml
     * @tags documents
     * @produces application/yaml
     */
    openapiYml: (): string => r.url("/openapi.yml", {}, true),
    /**
     * The same document as JSON
     * @route GET /openapi.json
     * @tags documents
     */
    openapiJson: (): Promise<unknown> => r.json("GET", r.url("/openapi.json", {}, true), undefined, undefined, false),
    /**
     * The box at a glance: the cards, the models, the services, the drives, the downloads (the page polls it)
     * @route GET /api/state
     * @tags page
     */
    state: (): Promise<State> => r.json("GET", r.url("/api/state", {}, true), undefined, undefined, false),
    /**
     * The settings file and what each setting is
     * @route GET /api/config
     * @tags page
     */
    config: (): Promise<Config> => r.json("GET", r.url("/api/config", {}, true), undefined, undefined, false),
    /**
     * The API tab: the token and the document with it in the examples
     * @route GET /api/spec
     * @tags page
     */
    spec: (): Promise<Spec> => r.json("GET", r.url("/api/spec", {}, true), undefined, undefined, false),
    /**
     * A run's output (its last 64 KiB)
     * @route GET /api/runs/{id}
     * @tags page
     */
    run: (req: RunId): Promise<RunView> => r.json("GET", r.url("/api/runs/{id}", req, true), undefined, undefined, false),
    /**
     * A page button: enable, disable, gpus, load, unload, config, restart, maintenance, measure, move, move_cancel, pull, pull_cancel, auto_pull; a load, a measurement and a move run on (the state shows them), the others answer when done
     * @route POST /api/action
     * @tags page
     */
    action: (req: Action): Promise<Record<string, unknown>> => r.json("POST", r.url("/api/action", req, false), JSON.stringify(req), "application/json", false),
  };
}
